// GUARDRAIL 1: Verification Challenge (GET) + payload validation (POST)
const body = $input.all()[0].json;
const qs = body.query || {};
if (qs['hub.mode'] === 'subscribe') {
  const tok = ($env['WEBHOOK_VERIFY_TOKEN'] || '');
  if (qs['hub.verify_token'] === tok)
    return [{ json: { type: 'CHALLENGE', challenge: qs['hub.challenge'] } }];
  return [{ json: { type: 'INVALID', reason: 'bad_token' } }];
}
const msgs = body?.entry?.[0]?.changes?.[0]?.value?.messages;
if (!msgs || !msgs.length) return [{ json: { type: 'INVALID', reason: 'no_messages' } }];
return [{ json: { type: 'VALID', body } }];
